#!/usr/bin/env node
/**
 * cron-weekly-runner.cjs — SessionStart hook: consolidated weekly cron tasks
 *
 * Combines 3 former weekly hooks into one sequential runner:
 *   1. metaLearnerWeekly  — writes ISO-week digest + Hebbian edge decay
 *   2. cognitiveConsolidation — launches consolidation orchestrator (detached) if >=12h or >50 new items
 *   3. brainRefreshWeekly — spawns brain-refresh-weekly.py (detached) if >7 days since last run
 *
 * All tasks are fail-open. Exit 0 always. Non-blocking.
 */

'use strict';

const fs = require('fs');
const path = require('path');
const { spawnSync, spawn } = require('child_process');

let isHookEnabled;
try {
  ({ isHookEnabled } = require('./lib/ck-config-utils.cjs'));
} catch {
  isHookEnabled = () => true;
}

if (!isHookEnabled('cron-weekly-runner')) {
  process.exit(0);
}

const DEBUG = !!process.env.CK_DEBUG;

function log(tag, msg) {
  if (DEBUG) console.error(`[${tag}] ${msg}`);
}

// ---------------------------------------------------------------------------
// Shared helpers
// ---------------------------------------------------------------------------

function isoWeekId(date) {
  const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
  const day = d.getUTCDay() || 7;
  d.setUTCDate(d.getUTCDate() + 4 - day);
  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  const week = Math.ceil(((d - yearStart) / 86400000 + 1) / 7);
  return `${d.getUTCFullYear()}-W${String(week).padStart(2, '0')}`;
}

// ---------------------------------------------------------------------------
// Task 1: Meta-learner weekly digest + Hebbian edge decay
// ---------------------------------------------------------------------------

function metaLearnerWeekly(repoRoot) {
  const tag = 'meta-learner';
  try {
    const weekId = isoWeekId(new Date());
    const digestPath = path.join(repoRoot, 'data', 'meta-learning', `${weekId}-digest.md`);

    if (fs.existsSync(digestPath)) return; // already written this week

    const pythonExe = path.join(repoRoot, '.claude', 'skills', '.venv', 'Scripts', 'python.exe');
    const script = path.join(repoRoot, '.claude', 'skills', 'business', 'compound', 'meta-learning-weekly-digest.py');

    if (!fs.existsSync(pythonExe) || !fs.existsSync(script)) return;

    const result = spawnSync(pythonExe, [script], { encoding: 'utf-8', timeout: 30000 });
    if (DEBUG && result.stderr) log(tag, result.stderr.trim());
    if (DEBUG && result.error) log(tag, result.error.message);

    // Hebbian edge decay (skipped internally if already ran this week)
    const decayScript = path.join(repoRoot, '.claude', 'skills', 'business', 'feedback_loop', 'hebbian-edge-decay.py');
    if (fs.existsSync(decayScript)) {
      const dr = spawnSync(pythonExe, [decayScript], { encoding: 'utf-8', timeout: 15000 });
      if (DEBUG && dr.stderr) log(tag, `decay: ${dr.stderr.trim()}`);
    }

    if (fs.existsSync(digestPath)) {
      const output = {
        hookSpecificOutput: {
          hookEventName: 'SessionStart',
          additionalContext: `Weekly meta-learner digest written: data/meta-learning/${weekId}-digest.md`,
        },
      };
      console.log(JSON.stringify(output));
    }
  } catch (e) {
    log(tag, e.message);
  }
}

// ---------------------------------------------------------------------------
// Task 2: Cognitive consolidation (detached, >=12h or >50 new items)
// ---------------------------------------------------------------------------

function cognitiveConsolidation(repoRoot) {
  const tag = 'cognitive-cron';
  try {
    const cogRoot = path.join(repoRoot, 'data', 'cognitive');
    const customDir = path.join(cogRoot, 'custom');
    const logPath = path.join(customDir, 'consolidation-log.jsonl');
    const cronLog = path.join(customDir, 'consolidation-cron.log');
    const pendingDb = path.join(customDir, 'pending-inferences.db');
    const bayesianDb = path.join(customDir, 'bayesian.db');

    const pythonExe = path.join(cogRoot, '.venv', 'Scripts', 'python.exe');
    const script = path.join(cogRoot, 'scripts', 'consolidate', 'cognitive-consolidate.py');

    if (!fs.existsSync(pythonExe) || !fs.existsSync(script)) return;

    function lastRunEntry() {
      if (!fs.existsSync(logPath)) return null;
      try {
        const lines = fs.readFileSync(logPath, 'utf8').trim().split('\n').filter(Boolean);
        for (let i = lines.length - 1; i >= 0; i--) {
          try {
            const e = JSON.parse(lines[i]);
            if (e.action === 'consolidate_run' && e.finished_at) return e.finished_at;
          } catch (_) {}
        }
      } catch (_) {}
      return null;
    }

    const lastIso = lastRunEntry();
    const hoursAgo = lastIso ? (Date.now() - new Date(lastIso).getTime()) / 3600000 : Infinity;

    let newItems = 0;
    const since = lastIso ? new Date(lastIso).getTime() : 0;
    for (const db of [pendingDb, bayesianDb]) {
      if (!fs.existsSync(db)) continue;
      try {
        const stat = fs.statSync(db);
        if (stat.mtimeMs > since) newItems += Math.max(1, Math.floor(stat.size / 200));
      } catch (_) {}
    }

    const shouldRun = process.env.COGNITIVE_CRON_FORCE === '1' || hoursAgo >= 12 || newItems > 50;
    if (!shouldRun) {
      log(tag, `skipped (hours=${hoursAgo.toFixed(1)}, new=${newItems})`);
      return;
    }

    fs.mkdirSync(customDir, { recursive: true });
    const out = fs.openSync(cronLog, 'a');
    const err = fs.openSync(cronLog, 'a');
    const child = spawn(pythonExe, [script], {
      cwd: cogRoot, detached: true, stdio: ['ignore', out, err], windowsHide: true,
    });
    child.unref();
    log(tag, `launched pid=${child.pid} (hours=${hoursAgo.toFixed(1)}, new=${newItems})`);
  } catch (e) {
    log(tag, e.message);
  }
}

// ---------------------------------------------------------------------------
// Task 3: Brain refresh weekly (detached, >7 days since last run)
// ---------------------------------------------------------------------------

function brainRefreshWeekly(repoRoot) {
  const tag = 'brain-refresh';
  try {
    let enabled = true;
    let minDays = 7;
    try {
      const cfg = JSON.parse(fs.readFileSync(path.join(repoRoot, '.claude', '.ck.json'), 'utf-8'));
      enabled = cfg?.stage0?.brainRefresh?.enabled ?? true;
      minDays = cfg?.stage0?.brainRefresh?.minIntervalDays ?? 7;
    } catch (_) {}

    if (!enabled) return;

    const calDir = path.join(repoRoot, 'data', 'calibration');
    let latestMtime = 0;
    try {
      const files = fs.readdirSync(calDir).filter(f => f.startsWith('brain-refresh-') && f.endsWith('.md'));
      for (const f of files) {
        const mt = fs.statSync(path.join(calDir, f)).mtimeMs;
        if (mt > latestMtime) latestMtime = mt;
      }
    } catch (_) {}

    const ageDays = (Date.now() - latestMtime) / 86400000;
    if (latestMtime > 0 && ageDays < minDays) return;

    const py = path.join(repoRoot, '.claude', 'skills', '.venv', 'Scripts', 'python.exe');
    const script = path.join(repoRoot, '.claude', 'skills', 'business', 'transaction-layer', 'nui-hunter', 'scripts', 'brain-refresh-weekly.py');

    if (!fs.existsSync(py) || !fs.existsSync(script)) return;

    const logDir = path.join(repoRoot, '.claude', 'hooks', '.logs');
    fs.mkdirSync(logDir, { recursive: true });
    const ageLabel = latestMtime === 0 ? 'never' : `${ageDays.toFixed(1)}d`;
    fs.appendFileSync(
      path.join(logDir, 'brain-refresh-trigger.log'),
      `${new Date().toISOString()} spawn brain-refresh-weekly.py (age=${ageLabel})\n`
    );

    const child = spawn(py, [script], { detached: true, stdio: 'ignore', cwd: repoRoot });
    child.unref();
    log(tag, `launched (age=${ageLabel})`);
  } catch (e) {
    log(tag, e.message);
  }
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

try {
  const repoRoot = path.resolve(__dirname, '..', '..');
  metaLearnerWeekly(repoRoot);
  cognitiveConsolidation(repoRoot);
  brainRefreshWeekly(repoRoot);
} catch (e) {
  if (DEBUG) console.error(`[cron-weekly-runner] ${e.message}`);
}

process.exit(0);

